     1	import {BoundsObserver} from '@react-ng/bounds-observer';
     2	import type {ForwardedRef} from 'react';
     3	import React, {forwardRef, memo, useCallback, useRef} from 'react';
     4	import type {LayoutRectangle} from 'react-native';
     5	import Hoverable from '@components/Hoverable';
     6	import GenericTooltip from '@components/Tooltip/GenericTooltip';
     7	import type TooltipProps from '@components/Tooltip/types';
     8	import * as DeviceCapabilities from '@libs/DeviceCapabilities';
     9	
    10	type MouseEvents = {
    11	    onMouseEnter: (e: MouseEvent) => void | undefined;
    12	};
    13	
    14	const hasHoverSupport = DeviceCapabilities.hasHoverSupport();
    15	
    16	/**
    17	 * A component used to wrap an element intended for displaying a tooltip. The term "tooltip's target" refers to the
    18	 * wrapped element, which, upon hover, triggers the tooltip to be shown.
    19	 */
    20	
    21	/**
    22	 * Choose the correct bounding box for the tooltip to be positioned against.
    23	 * This handles the case where the target is wrapped across two lines, and
    24	 * so we need to find the correct part (the one that the user is hovering
    25	 * over) and show the tooltip there.
    26	 *
    27	 * @param target The DOM element being hovered over.
    28	 * @param clientX The X position from the MouseEvent.
    29	 * @param clientY The Y position from the MouseEvent.
    30	 * @return The chosen bounding box.
    31	 */
    32	
    33	function chooseBoundingBox(target: HTMLElement, clientX: number, clientY: number): DOMRect {
    34	    const slop = 5;
    35	    const bbs = target.getClientRects();
    36	    const clientXMin = clientX - slop;
    37	    const clientXMax = clientX + slop;
    38	    const clientYMin = clientY - slop;
    39	    const clientYMax = clientY + slop;
    40	
    41	    // eslint-disable-next-line @typescript-eslint/prefer-for-of
    42	    for (let i = 0; i < bbs.length; i++) {
    43	        const bb = bbs[i];
    44	        if (clientXMin <= bb.right && clientXMax >= bb.left && clientYMin <= bb.bottom && clientYMax >= bb.top) {
    45	            return bb;
    46	        }
    47	    }
    48	
    49	    // If no matching bounding box is found, fall back to getBoundingClientRect.
    50	    return target.getBoundingClientRect();
    51	}
    52	
    53	function Tooltip({children, shouldHandleScroll = false, ...props}: TooltipProps, ref: ForwardedRef<BoundsObserver>) {
    54	    const target = useRef<HTMLElement | null>(null);
    55	    const initialMousePosition = useRef({x: 0, y: 0});
    56	
    57	    const updateTargetAndMousePosition = useCallback((e: MouseEvent) => {
    58	        if (!(e.currentTarget instanceof HTMLElement)) {
    59	            return;
    60	        }
    61	        target.current = e.currentTarget;
    62	        initialMousePosition.current = {x: e.clientX, y: e.clientY};
    63	    }, []);
    64	
    65	    /**
    66	     * Get the tooltip bounding rectangle
    67	     */
    68	    const getBounds = (bounds: DOMRect): LayoutRectangle => {
    69	        if (!target.current) {
    70	            return bounds;
    71	        }
    72	        // Choose a bounding box for the tooltip to target.
    73	        // In the case when the target is a link that has wrapped onto
    74	        // multiple lines, we want to show the tooltip over the part
    75	        // of the link that the user is hovering over.
    76	        return chooseBoundingBox(target.current, initialMousePosition.current.x, initialMousePosition.current.y);
    77	    };
    78	
    79	    const updateTargetPositionOnMouseEnter = useCallback(
    80	        (e: MouseEvent) => {
    81	            updateTargetAndMousePosition(e);
    82	            if (React.isValidElement(children)) {
    83	                const onMouseEnter = (children.props as MouseEvents).onMouseEnter;
    84	                onMouseEnter?.(e);
    85	            }
    86	        },
    87	        [children, updateTargetAndMousePosition],
    88	    );
    89	
    90	    // Skip the tooltip and return the children if the device does not support hovering
    91	    if (!hasHoverSupport) {
    92	        return children;
    93	    }
    94	
    95	    return (
    96	        // eslint-disable-next-line react/jsx-props-no-spreading
    97	        <GenericTooltip {...props}>
    98	            {({isVisible, showTooltip, hideTooltip, updateTargetBounds}) =>
    99	                // Checks if valid element so we can wrap the BoundsObserver around it
   100	                // If not, we just return the primitive children
   101	                React.isValidElement(children) ? (
   102	                    <BoundsObserver
   103	                        enabled={isVisible}
   104	                        onBoundsChange={(bounds) => {
   105	                            updateTargetBounds(getBounds(bounds));
   106	                        }}
   107	                        ref={ref}
   108	                    >
   109	                        <Hoverable
   110	                            onHoverIn={showTooltip}
   111	                            onHoverOut={hideTooltip}
   112	                            shouldHandleScroll={shouldHandleScroll}
   113	                        >
   114	                            {React.cloneElement(children as React.ReactElement, {
   115	                                onMouseEnter: updateTargetPositionOnMouseEnter,
   116	                            })}
   117	                        </Hoverable>
   118	                    </BoundsObserver>
   119	                ) : (
   120	                    children
   121	                )
   122	            }
   123	        </GenericTooltip>
   124	    );
   125	}
   126	
   127	Tooltip.displayName = 'Tooltip';
   128	
   129	export default memo(forwardRef(Tooltip));
